import * as React from 'react';
import { describe, it, expect, vi } from 'vitest';
import { render, screen, fireEvent, act } from '@testing-library/react';
import { Field } from '@base-ui/react/field';
import { Form } from '@base-ui/react/form';

describe('probe', () => {
  it('H1: submit-time validate arg for controlled number', () => {
    const validate = vi.fn(() => null);
    function App() {
      const [v] = React.useState(5);
      return (
        <Form>
          <Field.Root name="n" validate={validate}>
            <Field.Control value={v} onValueChange={() => {}} />
          </Field.Root>
          <button type="submit">go</button>
        </Form>
      );
    }
    render(<App />);
    fireEvent.click(screen.getByText('go'));
    console.log('H1 validate args', JSON.stringify(validate.mock.calls.map((c: any) => c[0])), typeof (validate.mock.calls[0] as any)?.[0]);
  });

  it('H2: controlled + preventDefault on input event', () => {
    const validate = vi.fn(() => null);
    function App() {
      const [v, setV] = React.useState('');
      return (
        <Field.Root validationMode="onChange" validate={validate}>
          <Field.Control value={v} onValueChange={setV} />
        </Field.Root>
      );
    }
    render(<App />);
    const c = screen.getByRole('textbox') as HTMLInputElement;
    c.addEventListener('input', (e) => e.preventDefault(), { capture: true, once: true });
    fireEvent.input(c, { cancelable: true, target: { value: 'a' } });
    console.log('H2 validate calls', validate.mock.calls.length);
  });

  it('H3: uncontrolled cancel still sets dirty/filled', () => {
    render(
      <Field.Root data-testid="root">
        <Field.Control onValueChange={(_v, d) => d.cancel()} />
      </Field.Root>,
    );
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
    const r = screen.getByTestId('root');
    console.log('H3 dirty', r.hasAttribute('data-dirty'), 'filled', r.hasAttribute('data-filled'));
  });

  it('H3b: controlled cancel + consumer still sets', () => {
    function App() {
      const [v, setV] = React.useState('');
      return (
        <Field.Root data-testid="root">
          <Field.Control value={v} onValueChange={(nv, d) => { d.cancel(); setV(nv); }} />
        </Field.Root>
      );
    }
    render(<App />);
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
    const r = screen.getByTestId('root');
    console.log('H3b dirty', r.hasAttribute('data-dirty'), 'filled', r.hasAttribute('data-filled'));
  });

  it('H4: controlled reject', () => {
    const validate = vi.fn(() => null);
    render(
      <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
        <Field.Control value="" onValueChange={() => {}} />
      </Field.Root>,
    );
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
    const r = screen.getByTestId('root');
    console.log('H4 dirty', r.hasAttribute('data-dirty'), 'filled', r.hasAttribute('data-filled'), 'validate', validate.mock.calls.length);
  });

  it('H5: async stale validator after programmatic change', async () => {
    const resolvers: Array<(v: string | null) => void> = [];
    const validate = vi.fn((_v: unknown) => new Promise<string | null>((res) => resolvers.push(res)));
    function App() {
      const [v, setV] = React.useState('');
      return (
        <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
          <Field.Control value={v} onValueChange={setV} />
          <Field.Error data-testid="err" />
          <button type="button" onClick={() => setV('next')}>set</button>
        </Field.Root>
      );
    }
    render(<App />);
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'old' } });
    fireEvent.click(screen.getByText('set'));
    await act(async () => { resolvers[0]('stale-error'); await Promise.resolve(); });
    console.log('H5 calls', validate.mock.calls.map((c: any) => c[0]), 'err', screen.queryByTestId('err')?.textContent ?? null);
    await act(async () => { resolvers[1]?.(null); await Promise.resolve(); });
  });

  it('H6: reset controlled to initial after change clears dirty; Form external error cleared on programmatic', () => {
    function App() {
      const [v, setV] = React.useState('init');
      return (
        <Form errors={{ f: 'Server' }}>
          <Field.Root name="f" data-testid="root">
            <Field.Control value={v} onValueChange={setV} />
            <Field.Error />
            <button type="button" onClick={() => setV('init')}>reset</button>
          </Field.Root>
        </Form>
      );
    }
    render(<App />);
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'x' } });
    console.log('H6 after type: err?', !!screen.queryByText('Server'), 'dirty', screen.getByTestId('root').hasAttribute('data-dirty'));
  });
});
